from sessions import purge_expired


class SessionStore:
    def __init__(self):
        self.sessions = []

    def add(self, user, expires):
        self.sessions.append({"user": user, "expires": expires})

    def purge(self, now):
        """Nightly job: drop expired sessions and report how many went."""
        return purge_expired(self.sessions, now)

    def users(self):
        return [s["user"] for s in self.sessions]

